class wf_flujoActions extends sfActions
{
  
  public function verificaPrilegio($currentForm)
  { 
  	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	if(!$this->getUser()->checkPerm($currentForm, $usuariologuiado)){
		$this->redirect(sfConfig::get('base_simad').'/no_autorizado.html');
	}
	 
  }
  
  public function verificaPrilegioCerrar($currentForm)
  { 
 	$usuarioLoguiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	if(!$this->getUser()->checkPerm($currentForm, $usuarioLoguiado)){
		$this->redirect(sfConfig::get('base_simad').'/no_autorizado.html');
	}
	 	  
  }
  
  public function executeIndex()
  {
    return $this->forward('wf_flujo', 'list');
  }

  public function executeList()
  {    
    $this->verificaPrilegio("workflow/list");
  	$c=new Criteria();
  	$this->parametros="a=1";
    //**********************************************************************************************
	$usuariologuiado = $this->getUser()->getAttribute('usuario_id','', 'subscriber');
    $entidad_conectado = $this->getUser()->getAttribute('entidad_id', '', 'subscriber');
    $regional_conectado = $this->getUser()->getAttribute('regional_id', '', 'subscriber');
    //**********************************************************************************************
  	$listall = $this->getUser()->checkPerm('LISTAR_FLUJOS_TODAS_ENTIDADES', $usuariologuiado);
  	$listsoloentidad = $this->getUser()->checkPerm('LISTAR_FLUJOS_SOLO_ENTIDAD', $usuariologuiado);
    $listsoloregional = $this->getUser()->checkPerm('LISTAR_FLUJOS_SOLO_REGIONAL', $usuariologuiado);
  	//**********************************************************************************************
  	if($this->getRequestParameter('wf_flujo_id')){	
	 $c->add(WfFlujoPeer::WF_FLUJO_ID,$this->getRequestParameter('wf_flujo_id'));		 
	 $this->parametros.="&wf_flujo_id=".$this->getRequestParameter('wf_flujo_id');			 	
	}
    //**********************************************************************************************
	if($this->getRequestParameter('wf_buzon_id')){	
	 $c->add(WfFlujoPeer::WF_BUZON_ID,$this->getRequestParameter('wf_buzon_id'));		 
	 $this->parametros.="&wf_buzon_id=".$this->getRequestParameter('wf_buzon_id');			 	
	}
	//**********************************************************************************************
    if(!$listall){
        $listent = $this->getUser()->checkPerm('LISTAR_FLUJOS_SOLO_ENTIDAD', $usuariologuiado);
        if($listent){
            $c->addJoin(WfFlujoPeer::REGIONAL_ID, RegionalPeer::REGIONAL_ID);
            $c->add(RegionalPeer::ENTIDAD_ID,$entidad_conectado);
        }else{
            $c->add(WfFlujoPeer::REGIONAL_ID,$regional_conectado);
        }
    }
	//**********************************************************************************************
  	$this->wf_flujos=WfFlujoPeer::doSelect($c);  	
  }

  public function executeShow()
  {
    $this->verificaPrilegioCerrar("workflow/show");
    $this->wf_flujo = WfFlujoPeer::retrieveByPk($this->getRequestParameter('wf_flujo_id'));
    $this->forward404Unless($this->wf_flujo);
  }

  public function executeCreate()
  {
    $this->verificaPrilegioCerrar("workflow/create");
    $this->wf_flujo = new WfFlujo();

    $this->setTemplate('edit');
  }

  public function executeEdit()
  {
    $this->verificaPrilegioCerrar("workflow/edit");
    $this->wf_flujo = WfFlujoPeer::retrieveByPk($this->getRequestParameter('wf_flujo_id'));
    $this->forward404Unless($this->wf_flujo);
  }

  public function executeUpdate()
  {
    if (!$this->getRequestParameter('wf_flujo_id'))
    {
      $wf_flujo = new WfFlujo();
      $wf_flujo->setEstaActivo(true);
    }
    else
    {
      $wf_flujo = WfFlujoPeer::retrieveByPk($this->getRequestParameter('wf_flujo_id'));
      $this->forward404Unless($wf_flujo);
    }
	//***************************************************************************************
    $buzon_id = 0;
    if($this->getRequestParameter('tipocomrecibida_id')){
        $buzon_id = 1;
    }elseif($this->getRequestParameter('tipocominterna_id')){
        $buzon_id = 2;
    }else{
        $buzon_id = $this->getRequestParameter('wf_buzon_id');
    }
    //***************************************************************************************
    $wf_flujo->setTipocomrecibidaId($this->getRequestParameter('tipocomrecibida_id') ? $this->getRequestParameter('tipocomrecibida_id') : null);
    $wf_flujo->setTipocominternaId($this->getRequestParameter('tipocominterna_id') ? $this->getRequestParameter('tipocominterna_id') : null);
    $wf_flujo->setWfBuzonId($buzon_id);
	$wf_flujo->setRegionalId($this->getRequestParameter('regional_id') ? $this->getRequestParameter('regional_id') : null);
    $wf_flujo->setDescripcion($this->getRequestParameter('descripcion'));
    $wf_flujo->save();
	//***************************************************************************************
    return $this->redirect($this->getRequest()->getScriptName().'/wf_flujo/show?wf_flujo_id='.$wf_flujo->getWfFlujoId());
  }
  
  public function executeEstadoFlujo()
  {
  	$wf_flujo = WfFlujoPeer::retrieveByPk($this->getRequestParameter('wf_flujo_id'));
    //***************************************************************************************
    if($wf_flujo->getEstaActivo()){
        $wf_flujo->setEstaActivo(false);        
    }else{
        $wf_flujo->setEstaActivo(true);
    }
    //***************************************************************************************
    $wf_flujo->save();
    //***************************************************************************************
    if($wf_flujo->getWfBuzonId() == 1){
        $tipo_com_recibida = $wf_flujo->getTipoComRecibida();
        $tipo_com_recibida->setEsAccionLegal($wf_flujo->getEstaActivo());
        $tipo_com_recibida->save();
    }elseif($wf_flujo->getWfBuzonId() == 2){
        $tipo_com_interna = $wf_flujo->getTipoComInterna();
        $tipo_com_interna->setEsVisible($wf_flujo->getEstaActivo());
        $tipo_com_interna->save();
    }
    //***************************************************************************************
    $this->wf_flujo = $wf_flujo;
  	$this->forward404Unless($wf_flujo);
  }
    
  public function executeDelete()
  {
    $this->verificaPrilegioCerrar("workflow/delete");
    $wf_flujo = WfFlujoPeer::retrieveByPk($this->getRequestParameter('wf_flujo_id'));

    $this->forward404Unless($wf_flujo);

    $wf_flujo->delete();

    return $this->redirect($this->getRequest()->getScriptName().'/wf_flujo/list');
  }
  
